"""Reconstruct July 2023 sales value from warehouse dispatches."""

import csv
import json
from datetime import datetime
from decimal import Decimal
from pathlib import Path


DATA = Path("/app/dataset")
DISPOSAL_TIME = datetime.fromisoformat("2023-07-18 03:17:00")


def read_csv(name: str) -> list[dict[str, str]]:
    with (DATA / name).open(newline="") as file:
        return list(csv.DictReader(file))


def number(value: str) -> Decimal:
    return Decimal(value.replace(",", "."))


def answer() -> int:
    catalog = read_csv("product_catalog.csv")
    by_product_id = {row["product_id"]: row for row in catalog}
    by_ean = {row["ean_code"]: row for row in catalog}
    safe_limits = {
        row["storage_category"].lower(): number(row["max_safe_temp_c"])
        for row in catalog
    }

    # The simultaneous meat and frozen dispatches at 03:17 were made while
    # both storage zones were above their safe temperatures on either side
    # of the dispatch time. That group is the disposal write-off.
    readings = {
        (datetime.fromisoformat(row["timestamp"]), row["zone"].lower()):
        number(row["temperature_c"])
        for row in read_csv("temperature_logs.csv")
    }
    for zone in ("meat", "frozen"):
        for time in ("2023-07-18 02:00:00", "2023-07-18 04:00:00"):
            assert readings[(datetime.fromisoformat(time), zone)] > safe_limits[zone]

    revenue = Decimal(0)
    disposal_count = 0
    for row in read_csv("warehouse_dispatches.csv"):
        time = datetime.fromisoformat(row["timestamp"])
        if time.year != 2023 or time.month != 7:
            continue

        # One dispatch uses the item's EAN instead of its internal product ID.
        product = by_product_id.get(row["product_id"])
        if product is None:
            product = by_ean[row["product_id"]]

        if time == DISPOSAL_TIME:
            assert product["storage_category"].lower() in {"meat", "frozen"}
            disposal_count += 1
            continue

        revenue += int(row["quantity"]) * number(product["unit_price"])

    assert disposal_count == 8
    assert revenue == int(revenue)
    return int(revenue)


if __name__ == "__main__":
    with Path("/app/answer.json").open("w") as file:
        json.dump(answer(), file)
